DROP TABLE IF EXISTS `ai_job`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_job` (
  `job_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `requester_id` bigint unsigned NOT NULL,
  `scope_key` varchar(255) NOT NULL,
  `workspace_path` varchar(500) NOT NULL,
  `status` varchar(30) NOT NULL,
  `document_ids` json NOT NULL,
  `document_results` json DEFAULT NULL,
  `document_change_types` json DEFAULT NULL,
  `failure_reason` varchar(1000) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `started_at` datetime(6) DEFAULT NULL,
  `finished_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`job_id`),
  KEY `idx_ai_job_requester` (`requester_id`),
  KEY `idx_ai_job_scope_status_created` (`scope_key`,`status`,`created_at`),
  CONSTRAINT `fk_ai_job_requester` FOREIGN KEY (`requester_id`) REFERENCES `member` (`member_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_ai_job_scope` FOREIGN KEY (`scope_key`) REFERENCES `wiki_scope` (`scope_key`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_ai_job_status` CHECK ((`status` in (_utf8mb4'WAITING',_utf8mb4'PROCESSING',_utf8mb4'COMPLETED',_utf8mb4'FAILED',_utf8mb4'CANCELLED')))
) ENGINE=InnoDB AUTO_INCREMENT=63 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

