DROP TABLE IF EXISTS `document`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `document` (
  `document_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uploader_id` bigint unsigned NOT NULL,
  `document_category_id` bigint unsigned DEFAULT NULL,
  `scope_key` varchar(255) NOT NULL,
  `original_file_name` varchar(255) NOT NULL,
  `original_path` varchar(500) NOT NULL,
  `parsed_path` varchar(500) DEFAULT NULL,
  `mime_type` varchar(100) NOT NULL,
  `file_size` bigint unsigned NOT NULL,
  `description` varchar(1000) DEFAULT NULL,
  `document_wiki_refs` json NOT NULL DEFAULT (json_array()),
  `status` varchar(30) NOT NULL,
  `failure_reason` varchar(1000) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`document_id`),
  KEY `idx_document_uploader` (`uploader_id`),
  KEY `idx_document_category` (`document_category_id`),
  KEY `idx_document_scope_status` (`scope_key`,`status`),
  CONSTRAINT `fk_document_category` FOREIGN KEY (`document_category_id`) REFERENCES `document_category` (`document_category_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_document_scope` FOREIGN KEY (`scope_key`) REFERENCES `wiki_scope` (`scope_key`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_document_uploader` FOREIGN KEY (`uploader_id`) REFERENCES `member` (`member_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_document_file_size` CHECK ((`file_size` <= 20971520)),
  CONSTRAINT `chk_document_status` CHECK ((`status` in (_utf8mb4'UPLOADED',_utf8mb4'PARSING',_utf8mb4'PROCESSING',_utf8mb4'DELETING',_utf8mb4'COMPLETED',_utf8mb4'FAILED',_utf8mb4'CANCELLED')))
) ENGINE=InnoDB AUTO_INCREMENT=81 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
