  CONSTRAINT `fk_inquiry_member` FOREIGN KEY (`member_id`) REFERENCES `member` (`member_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_inquiry_priority` CHECK ((`priority` in (_latin1'HIGH',_latin1'NORMAL',_latin1'LOW'))),
  CONSTRAINT `chk_inquiry_status` CHECK ((`status` in (_latin1'PENDING',_latin1'DONE')))
