INSERT INTO `inquiry` VALUES (1,2,7,'연차 잔여일수 확인 요청','올해 사용한 연차와 남은 일수를 알려주실 수 있을까요? 하계휴가 권장 기간에 맞춰 계획을 세우려고 합니다.','NORMAL','DONE','[]','2026-07-20 10:12:00.000000','2026-07-20 10:12:00.000000'),(2,19,7,'육아기 근로시간 단축 신청 절차','만 7세 자녀가 있어 근로시간 단축을 신청하려 합니다. 필요한 서류와 처리 기간을 알려주세요.','NORMAL','DONE','[]','2026-07-24 14:38:00.000000','2026-07-24 14:38:00.000000'),(3,14,1,'재택근무 주 3일 예외 신청','다음 달 가족 간병이 필요해 한 달간 주 3일 재택을 신청드립니다. 규정상 주 2일이 한도인 것은 알고 있습니다.','HIGH','DONE','[]','2026-07-28 09:05:00.000000','2026-07-28 09:05:00.000000'),(4,18,7,'건강검진 지정 병원 변경 가능한가요','안내받은 검진 기관이 집에서 멀어 다른 병원에서 받고 싶습니다. 가능한지 궁금합니다.','NORMAL','DONE','[]','2026-07-30 11:20:00.000000','2026-07-30 11:20:00.000000'),(5,21,7,'경조금 신청 시 증빙서류 원본 제출 여부','청첩장 원본을 내야 하나요, 사본이나 사진도 되나요?','LOW','DONE','[]','2026-08-03 16:45:00.000000','2026-08-03 16:45:00.000000'),(6,24,1,'개발용 노트북 교체 요청','사용 중인 장비의 빌드 시간이 크게 늘어 업무에 지장이 있습니다. 교체 기준이 어떻게 되는지 궁금합니다.','NORMAL','DONE','[]','2026-08-04 13:02:00.000000','2026-08-04 13:02:00.000000'),(7,6,5,'디자인 시스템 v2.1 적용 일정','진행 중인 화면에 v2.1 토큰을 언제부터 적용해야 하는지 알려주세요.','NORMAL','DONE','[]','2026-08-05 10:30:00.000000','2026-08-05 10:30:00.000000'),(8,8,9,'사내 헬스장 사물함 추가 배정 요청','이번 분기 추첨에서 탈락했는데 잔여 사물함이 있으면 배정 가능한지 문의드립니다.','LOW','DONE','[]','2026-08-05 17:55:00.000000','2026-08-05 17:55:00.000000'),(9,26,9,'통근버스 판교 노선 정차지 추가 요청','판교 노선에 정자역 정차를 추가해 주실 수 있을까요? 같은 방향 이용자가 여러 명 있습니다.','HIGH','PENDING','[]','2026-08-06 09:40:00.000000','2026-08-06 09:40:00.000000'),(10,17,5,'브랜드 로고 외부 제휴사 제공 가능 여부','제휴사 홍보물에 로고를 넣고 싶다는 요청을 받았습니다. 어떤 형식으로 어디까지 제공할 수 있나요?','HIGH','PENDING','[]','2026-08-06 15:12:00.000000','2026-08-06 15:12:00.000000'),(11,29,7,'사외 콘퍼런스 참가비 지원 한도 초과분 처리','참가비가 지원 한도를 넘습니다. 초과분을 개인 부담으로 처리하면 나머지는 지원받을 수 있나요?','NORMAL','PENDING','[]','2026-08-07 11:08:00.000000','2026-08-07 11:08:00.000000'),(12,23,7,'퇴사 예정자 잔여 연차 정산','퇴사일까지 사용하지 못한 연차의 정산 기준과 지급 시점을 알려주세요.','HIGH','PENDING','[]','2026-08-07 14:26:00.000000','2026-08-07 14:26:00.000000'),(13,34,9,'인사부 위키 열람 권한 요청','온보딩 과제로 인사 규정을 확인해야 하는데 인사부 위키가 보이지 않습니다. 열람 권한을 받을 수 있을까요?','NORMAL','PENDING','[]','2026-08-08 10:02:00.000000','2026-08-08 10:02:00.000000'),(14,22,7,'출장 중 심야 이동 교통비 인정 범위','막차가 끊겨 택시를 이용했습니다. 실비 인정이 되는지, 사전 승인이 필요한 건인지 확인 부탁드립니다.','NORMAL','PENDING','[]','2026-08-08 18:33:00.000000','2026-08-08 18:33:00.000000');
