--
-- Table structure for table `schedule`
--

DROP TABLE IF EXISTS `schedule`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `schedule` (
  `schedule_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `author_id` bigint unsigned NOT NULL,
  `source_group_key` varchar(100) DEFAULT NULL,
  `source_original_path` varchar(500) DEFAULT NULL,
  `source_original_file_name` varchar(255) DEFAULT NULL,
  `source_parsed_path` varchar(500) DEFAULT NULL,
  `title` varchar(200) NOT NULL,
  `content` text,
  `target_text` varchar(500) DEFAULT NULL,
  `location` varchar(200) DEFAULT NULL,
  `visibility_type` varchar(30) NOT NULL,
  `start_at` datetime(6) NOT NULL,
  `end_at` datetime(6) NOT NULL,
  `status` varchar(30) NOT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`schedule_id`),
  KEY `idx_schedule_author` (`author_id`),
  KEY `idx_schedule_source_group` (`source_group_key`),
  KEY `idx_schedule_period_status` (`start_at`,`end_at`,`status`),
  CONSTRAINT `fk_schedule_author` FOREIGN KEY (`author_id`) REFERENCES `member` (`member_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_schedule_period` CHECK ((`end_at` >= `start_at`)),
  CONSTRAINT `chk_schedule_status` CHECK ((`status` in (_latin1'DRAFT',_latin1'APPROVED'))),
  CONSTRAINT `chk_schedule_visibility` CHECK ((`visibility_type` in (_latin1'ALL',_latin1'DEPARTMENT',_latin1'PERSONAL')))
) ENGINE=InnoDB AUTO_INCREMENT=479 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

