/*!40000 ALTER TABLE `schedule` DISABLE KEYS */;
INSERT INTO `schedule` VALUES (9,1,'schedule-source-20260803-340a04e9','schedule-sources/schedule-source-20260803-340a04e9/original/source.md','01-august-notice.md','schedule-sources/schedule-source-20260803-340a04e9/parsed/content.md','하계 워크샵',NULL,'개발부, 디자인부 전 직원','강원도 속초 리조트','ALL','2026-08-12 00:00:00.000000','2026-08-13 09:00:00.000000','DRAFT','2026-08-03 08:28:49.276000','2026-08-03 08:28:49.276000'),(10,1,'schedule-source-20260803-340a04e9','schedule-sources/schedule-source-20260803-340a04e9/original/source.md','01-august-notice.md','schedule-sources/schedule-source-20260803-340a04e9/parsed/content.md','하계 워크샵 참가 신청 마감','인사팀으로 제출','개발부, 디자인부',NULL,'ALL','2026-08-04 15:00:00.000000','2026-08-05 14:59:59.999999','DRAFT','2026-08-03 08:28:49.286000','2026-08-03 08:28:49.286000'),(11,1,'schedule-source-20260803-340a04e9','schedule-sources/schedule-source-20260803-340a04e9/original/source.md','01-august-notice.md','schedule-sources/schedule-source-20260803-340a04e9/parsed/content.md','정기 안전교육','필수 참석','전 직원','본사 5층 대강당','ALL','2026-08-20 05:00:00.000000','2026-08-20 07:00:00.000000','DRAFT','2026-08-03 08:28:49.287000','2026-08-03 08:28:49.287000'),(12,1,'schedule-source-20260803-340a04e9','schedule-sources/schedule-source-20260803-340a04e9/original/source.md','01-august-notice.md','schedule-sources/schedule-source-20260803-340a04e9/parsed/content.md','8월 급여 지급',NULL,NULL,NULL,'ALL','2026-08-24 15:00:00.000000','2026-08-25 14:59:59.999999','DRAFT','2026-08-03 08:28:49.289000','2026-08-03 08:28:49.289000'),(375,7,NULL,NULL,NULL,NULL,'미사용 연차 사용 촉진 안내','사용기간 종료 6개월 전 기준 서면 촉구. 잔여 연차를 확인하고 사용 시기를 등록한다.','전 직원',NULL,'ALL','2026-06-30 15:00:00.000000','2026-07-01 14:59:59.999999','APPROVED','2026-08-09 07:05:21.363274','2026-08-09 07:05:21.363274'),(376,7,NULL,NULL,NULL,NULL,'상반기 성과 리뷰 면담','팀장과 1:1 면담을 진행한다. 면담 일정은 팀별로 조율한다.','전 직원',NULL,'ALL','2026-07-12 15:00:00.000000','2026-07-24 14:59:59.999999','APPROVED','2026-08-09 07:05:21.363510','2026-08-09 07:05:21.363510'),(377,7,NULL,NULL,NULL,NULL,'하계휴가 권장 기간','이 기간에 연차 사용을 권장한다. 팀별로 최소 인원은 유지한다.','전 직원',NULL,'ALL','2026-08-02 15:00:00.000000','2026-08-14 14:59:59.999999','APPROVED','2026-08-09 07:05:21.363677','2026-08-09 07:05:21.363677'),(378,9,NULL,NULL,NULL,NULL,'사내 헬스장 정기 점검 휴관','설비 점검으로 하루 휴관한다. 샤워실도 함께 이용할 수 없다.','전 직원','지하 1층 헬스장','ALL','2026-08-16 15:00:00.000000','2026-08-17 14:59:59.999999','APPROVED','2026-08-09 07:05:21.363919','2026-08-09 07:05:21.363919'),(379,9,NULL,NULL,NULL,NULL,'8월 전사 타운홀','분기 실적 공유와 질의응답. 온라인 중계도 함께 진행한다.','전 직원','본사 5층 대강당','ALL','2026-08-28 07:00:00.000000','2026-08-28 08:30:00.000000','APPROVED','2026-08-09 07:05:21.364036','2026-08-09 07:05:21.364036'),(380,7,NULL,NULL,NULL,NULL,'2026년 종합건강검진 기간','연 1회 종합건강검진. 검진 당일은 유급으로 처리하며 연차를 차감하지 않는다. 배우자 검진은 본인 검진의 50퍼센트 범위에서 지원한다.','전 직원',NULL,'ALL','2026-08-31 15:00:00.000000','2026-09-30 14:59:59.999999','APPROVED','2026-08-09 07:05:21.364154','2026-08-09 07:05:21.364154'),(381,9,NULL,NULL,NULL,NULL,'통근버스 노선 개편 시행','강남·판교·잠실 3개 노선의 정차지를 조정한다. 본사 08시 40분 도착 기준은 유지한다.','통근버스 이용자',NULL,'ALL','2026-08-31 15:00:00.000000','2026-09-01 14:59:59.999999','APPROVED','2026-08-09 07:05:21.364284','2026-08-09 07:05:21.364284'),(382,7,NULL,NULL,NULL,NULL,'창립기념일 휴무','전사 휴무. 연차를 차감하지 않는다.','전 직원',NULL,'ALL','2026-09-14 15:00:00.000000','2026-09-15 14:59:59.999999','APPROVED','2026-08-09 07:05:21.364405','2026-08-09 07:05:21.364405'),(383,7,NULL,NULL,NULL,NULL,'9월 급여 지급 (연휴로 앞당김)','정기 지급일인 24일이 추석 연휴와 겹쳐 23일에 지급한다.','전 직원',NULL,'ALL','2026-09-22 15:00:00.000000','2026-09-23 14:59:59.999999','APPROVED','2026-08-09 07:05:21.364513','2026-08-09 07:05:21.364513'),(384,7,NULL,NULL,NULL,NULL,'추석 연휴',NULL,'전 직원',NULL,'ALL','2026-09-23 15:00:00.000000','2026-09-26 14:59:59.999999','APPROVED','2026-08-09 07:05:21.364641','2026-08-09 07:05:21.364641'),(385,9,NULL,NULL,NULL,NULL,'4분기 OKR 수립 워크숍','부서별 4분기 목표를 정리해 사전 공유한다.','팀장 이상','본사 5층 대회의실','ALL','2026-09-29 01:00:00.000000','2026-09-29 08:00:00.000000','APPROVED','2026-08-09 07:05:21.364754','2026-08-09 07:05:21.364754'),(386,9,NULL,NULL,NULL,NULL,'정보보안 교육 이수 마감','온라인 과정 이수 후 수료증을 제출한다. 미이수자는 재수강 대상이다.','전 직원',NULL,'ALL','2026-10-29 15:00:00.000000','2026-10-30 14:59:59.999999','APPROVED','2026-08-09 07:05:21.364865','2026-08-09 07:05:21.364865'),(387,9,NULL,NULL,NULL,NULL,'10월 전사 타운홀','일정 확정 전 초안이다.','전 직원','본사 5층 대강당','ALL','2026-10-30 07:00:00.000000','2026-10-30 08:30:00.000000','DRAFT','2026-08-09 07:05:21.364967','2026-08-09 07:05:21.364967'),(388,1,NULL,NULL,NULL,NULL,'스프린트 계획 회의','이번 스프린트 백로그를 확정한다.','개발부 전원','본사 3층 소회의실','DEPARTMENT','2026-08-10 01:00:00.000000','2026-08-10 03:00:00.000000','APPROVED','2026-08-09 07:05:21.365077','2026-08-09 07:05:21.365077'),(389,1,NULL,NULL,NULL,NULL,'스프린트 계획 회의','이번 스프린트 백로그를 확정한다.','개발부 전원','본사 3층 소회의실','DEPARTMENT','2026-08-24 01:00:00.000000','2026-08-24 03:00:00.000000','APPROVED','2026-08-09 07:05:21.365377','2026-08-09 07:05:21.365377'),(390,1,NULL,NULL,NULL,NULL,'스프린트 계획 회의','이번 스프린트 백로그를 확정한다.','개발부 전원','본사 3층 소회의실','DEPARTMENT','2026-09-07 01:00:00.000000','2026-09-07 03:00:00.000000','APPROVED','2026-08-09 07:05:21.365504','2026-08-09 07:05:21.365504'),(391,1,NULL,NULL,NULL,NULL,'스프린트 계획 회의','이번 스프린트 백로그를 확정한다.','개발부 전원','본사 3층 소회의실','DEPARTMENT','2026-09-21 01:00:00.000000','2026-09-21 03:00:00.000000','APPROVED','2026-08-09 07:05:21.365610','2026-08-09 07:05:21.365610'),(392,1,NULL,NULL,NULL,NULL,'스프린트 회고',NULL,'개발부 전원','본사 3층 소회의실','DEPARTMENT','2026-08-21 06:00:00.000000','2026-08-21 07:30:00.000000','APPROVED','2026-08-09 07:05:21.365751','2026-08-09 07:05:21.365751'),(393,1,NULL,NULL,NULL,NULL,'스프린트 회고',NULL,'개발부 전원','본사 3층 소회의실','DEPARTMENT','2026-09-04 06:00:00.000000','2026-09-04 07:30:00.000000','APPROVED','2026-08-09 07:05:21.365884','2026-08-09 07:05:21.365884'),(394,1,NULL,NULL,NULL,NULL,'스프린트 회고',NULL,'개발부 전원','본사 3층 소회의실','DEPARTMENT','2026-09-18 06:00:00.000000','2026-09-18 07:30:00.000000','APPROVED','2026-08-09 07:05:21.365986','2026-08-09 07:05:21.365986'),(3