INSERT INTO `wiki_chat_message` VALUES (1,8,'부업(Side Gig) 정책',1,'ADMIN','부업 신청 절차를 한 문장으로 요약하는 섹션을 맨 위에 추가해줘','2026-08-03 07:08:13.694194'),(2,8,'부업(Side Gig) 정책',NULL,'AGENT','완료. 작업 내용 요약:\n\n1. **`## 요약` 섹션을 맨 위(본문 첫 문단 앞)에 추가** — \"부업을 시작하기 전에 소속 팀의 소속 팀의 임원에게 사전 확인을 받아야 한다\" 한 문장으로 작성, 기존 각주 `[^13]`(02-side-gigs.md, Getting signoff)을 근거로 사용.\n\n2. **각주 문서명 일괄 수정** — 기존 각주 전체가 `document-32`(존재하지 않는 ID)를 참조하고 있어 올바른 문서명 `02-side-gigs.md`로 교체. (이는 이번 편집 전부터 있던 오류였으나, lint가 이번 작업 대상 페이지를 검사하면서 error로 잡혔기 때문에 함께 수정함)\n\n3. **`index.md` 수정 불필요** — 기존 요약이 \"사전 승인 절차\"를 이미 포함하고 있어 변경 없음.','2026-08-03 07:08:13.743261'),(5,12,'보상 체계 및 급여 리뷰',9,'ADMIN','보상 체계 및 급여 리뷰에 연간 2~3회 급여 리뷰를 통해 구성원이 협상을 요청하지 않아도 적정 보상을 받는다고 되어 있는데, 2~4회로 변경됐어. 수정해줘','2026-08-04 15:59:34.125062'),(6,12,'보상 체계 및 급여 리뷰',NULL,'AGENT','「보상 체계 및 급여 리뷰」 페이지 본문 두 곳에서 \"연간 2~3회\"를 \"연간 2~4회\"로 수정했습니다. 첫 문단 요약과 「급여 리뷰 프로세스」 절 모두 바꿨으며, 목차의 소개 문구도 \"연 2~4회\"로 함께 맞췄습니다.','2026-08-04 15:59:34.186136'),(11,10,'주식 옵션(Equity) 안내',9,'ADMIN','주식 옵션에서 퇴사 후 8년 이내 행사 가능이야 수정해','2026-08-06 00:10:20.282587'),(12,10,'주식 옵션(Equity) 안내',NULL,'AGENT','「주식 옵션(Equity) 안내」 페이지의 퇴사 후 행사 기간을 \"10년 이내\"에서 \"8년 이내\"로 수정했습니다. 주요 조건 표와 베스팅 흐름도, 그리고 해당 근거 항목 모두 8년으로 함께 맞췄으며, 이번 관리자 지시를 변경 근거로 추가했습니다.','2026-08-06 00:10:20.307456');
